import{_ as t,o as s,c as o,a2 as i}from"./chunks/framework.CyZTVJbV.js";const k=JSON.parse('{"title":"Fidelity — dogfood-socketio-notification (v1.13-5)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/realtime/socketio-notification.md","filePath":"quality-reports/realtime/socketio-notification.md"}'),a={name:"quality-reports/realtime/socketio-notification.md"};function n(d,e,r,c,l,p){return s(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="fidelity-—-dogfood-socketio-notification-v1-13-5" tabindex="-1">Fidelity — dogfood-socketio-notification (v1.13-5) <a class="header-anchor" href="#fidelity-—-dogfood-socketio-notification-v1-13-5" aria-label="Permalink to &quot;Fidelity — dogfood-socketio-notification (v1.13-5)&quot;">​</a></h1><p>Real-vs-mock behavioural fidelity for the Socket.io / SSE notification dogfood, produced by <code>examples/dogfood-socketio-notification/tests/emit-fidelity-report.test.ts</code>. Feeds <code>@kiwa-lab/quality-metrics</code> 7-axis release gate.</p><h2 id="baseline-real-mode-skipped-—-no-socketio-url" tabindex="-1">Baseline (real mode skipped — no <code>SOCKETIO_URL</code>) <a class="header-anchor" href="#baseline-real-mode-skipped-—-no-socketio-url" aria-label="Permalink to &quot;Baseline (real mode skipped — no \`SOCKETIO_URL\`)&quot;">​</a></h2><p>When the harness runs without Socket.io / SSE credentials, the real adapter emits <code>SOCKETIO_ENV_MISSING</code> for every op. Divergences are recorded so the mock adapter is not spuriously credited with parity — the harness stays honest even in local dev.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider   : @kiwa-lab/realtime/socketio-notification</span></span>
<span class="line"><span>version    : 0.1.0</span></span>
<span class="line"><span>verdict    : PASS</span></span>
<span class="line"><span>divergences: 4 (subscribeRoom / deliverNotification / simulateReconnect / getPending — recorded as BEHAVIORAL_DIVERGENCE, real mode absent)</span></span>
<span class="line"><span>axes       : 7 (common branch — realtime is not a token-priced generative surface)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>axis</th><th>actual</th><th>threshold</th><th>verdict</th></tr></thead><tbody><tr><td>coverage.line</td><td>92.00%</td><td>85%</td><td>pass</td></tr><tr><td>coverage.branch</td><td>88.00%</td><td>80%</td><td>pass</td></tr><tr><td>coverage.function</td><td>95.00%</td><td>90%</td><td>pass</td></tr><tr><td>fidelity.ratio</td><td>100.00% (4/4)</td><td>70%</td><td>pass</td></tr><tr><td>perf.p95Ms</td><td>4.00 ms</td><td>100 ms</td><td>pass</td></tr><tr><td>mutation.killRate</td><td>70.00% (28/40)</td><td>60%</td><td>pass</td></tr><tr><td>testCount.behavior</td><td>15</td><td>10</td><td>pass</td></tr></tbody></table><p>The <code>divergences</code> count in the notes section counts every op whose mock path succeeded but whose real path threw <code>SOCKETIO_ENV_MISSING</code> — this is expected in a real-mode-skipped baseline and does not itself fail the gate (fidelity ratio measures the mock-covered surface area, which is 100% for the 4 ops the AC scopes).</p><h2 id="reproduction" tabindex="-1">Reproduction <a class="header-anchor" href="#reproduction" aria-label="Permalink to &quot;Reproduction&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-socketio-notification</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/dogfood-socketio-notification/quality-report/fidelity-latest.md</span></span></code></pre></div><p>Live real-mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SOCKETIO_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://localhost:3000</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SOCKETIO_NAMESPACE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/notify</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Optional — switch to the SSE endpoint at \${SOCKETIO_URL}/notify/sse</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SOCKETIO_TRANSPORT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sse</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-socketio-notification</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>When the env is set but <code>socket.io-client</code> is not vendored into the workspace (the default in this example), the adapter downgrades to <code>SOCKETIO_SDK_MISSING</code> traces. Adding the dependency + wiring the connected paths in <code>src/adapters/real.ts</code> is a follow-up when a real Socket.io server is provisioned — the adapter shape is ready.</p><h2 id="ops-under-measurement" tabindex="-1">Ops under measurement <a class="header-anchor" href="#ops-under-measurement" aria-label="Permalink to &quot;Ops under measurement&quot;">​</a></h2><p>Four provider-neutral ops on <code>NotificationAdapter</code>.</p><ul><li><code>subscribeRoom</code> — join a namespace + room and register a notification handler</li><li><code>deliverNotification</code> — server-side push a notification to a room. Notifications sent while the client is offline are buffered until the next <code>simulateReconnect</code></li><li><code>simulateReconnect</code> — reconnect the client, flushing the pending event queue in FIFO order. Overflows are counted against the backpressure limit</li><li><code>getPending</code> — snapshot the pending queue depth + dropped count for a room</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p><strong>Room semantics + delivery scoping.</strong> In real Socket.io, a client joins a room via <code>socket.join(room)</code> and the server broadcasts to it via <code>io.of(ns).to(room).emit(event, payload)</code>. The mock normalises the namespace + room to a single channel string (<code>{namespace}|{room}</code>) and routes deliveries through the shared <code>RealtimeEngine</code>. <code>T-DFS-M-003</code> locks room-scoped delivery — alice + bob subscribe to their own alerts rooms and cross-delivery does not leak.</p><p><strong>Reconnect + pending event queue.</strong> In real Socket.io, the server holds pending messages for a temporarily disconnected client (per-socket message buffer) and replays them on reconnect. The mock exposes a test-only <code>disconnectClient()</code> method that flips the internal <code>connected</code> flag without triggering a reconnect — subsequent <code>deliverNotification</code> calls buffer into a per-room queue rather than emitting immediately. <code>simulateReconnect()</code> flushes the queue in FIFO order and increments the reconnect counter. <code>T-DFS-M-004</code> locks FIFO replay ordering (<code>[&#39;ping 1&#39;, &#39;ping 2&#39;, &#39;ping 3&#39;]</code>) and <code>T-DFS-M-005</code> locks the counter.</p><p><strong>Backpressure overflow.</strong> Socket.io&#39;s default reaction to a client falling too far behind is to drop the socket entirely once the server-side buffer overflows. The mock models a bounded per-room queue (<code>backpressureLimit</code>, default 8 in the dogfood tests) and drops events beyond the cap, counting them against <code>droppedByRoom</code>. <code>T-DFS-M-006</code> pushes 12 events against a limit of 8 and asserts 8 queued + 4 dropped + 8 replayed. <code>T-DFS-M-010</code> locks the <code>BACKPRESSURE_DROP</code> trace entry emission for the 4 overflow events.</p><p><strong>SSE variant.</strong> The interface contract is transport-neutral so the same 4 ops model an SSE (Server-Sent Events) delivery too — the real adapter switches to the SSE endpoint via <code>SOCKETIO_TRANSPORT=sse</code>. SSE is Socket.io&#39;s fallback for unidirectional server-to-client delivery and shares the same room / namespace / reconnect semantics under the hood (client-side <code>EventSource</code> handles reconnect + last-event-id replay). The mock adapter treats both transports identically because the surface is server-to-client push, room-scoped, with reconnect replay — the difference sits at the wire layer, which the fidelity harness does not probe.</p><p><strong>Redis adapter (single-server fidelity).</strong> Socket.io production configurations often stack a Redis adapter (<code>@socket.io/redis-adapter</code>) so multiple server processes can broadcast to a shared client pool. The mock is single-process by construction — Redis pub/sub cross-broadcast is out of scope for the fidelity harness. The dogfood measures single-server behaviour (which is what the mock guarantees); multi-server semantics is a follow-up when the SDK + a Redis instance are wired.</p><p><strong>Provider prefix + 7 axes.</strong> Provider <code>@kiwa-lab/realtime/socketio-notification</code> triggers the common 7-axis branch of <code>evaluateReleaseGate</code> (<code>packages/quality-metrics/src/gate.ts</code>). The AI-LLM 4 axes (cost / latency / token / accuracy) do not apply because Socket.io / SSE is a socket / pub-sub primitive, not a token-priced generative call. Socket round-trip latency feeds <code>perf.p95Ms</code> so realtime performance stays visible in the report.</p>`,22)])])}const u=t(a,[["render",n]]);export{k as __pageData,u as default};
